def max_uptime(status, k):
    kiri = 0
    zeros = 0
    terbaik = 0
    for kanan in range(len(status)):
        if status[kanan] == 0:
            zeros += 1
        while zeros > k:
            if status[kiri] == 0:
                zeros -= 1
            kiri += 1
        terbaik = max(terbaik, kanan - kiri + 1)
    return terbaik
